const CSS=".card{position:relative;box-sizing:border-box;width:100%;height:100%;min-width:0;min-height:0;display:flex;flex-direction:column;gap:6px;padding:8px;overflow:hidden;color:var(--ink);user-select:none;-webkit-user-select:none}\n.card *{box-sizing:border-box}\nbutton{font:inherit;color:inherit;background:none;border:0;padding:0;margin:0;cursor:pointer;touch-action:manipulation;-webkit-tap-highlight-color:transparent}\nbutton:disabled{cursor:default}\nbutton:focus-visible{outline:2px solid var(--accent);outline-offset:2px}\nsvg{display:block}\n\n/* \u6700\u8fd1\u4e00\u6b21\u8bb0\u5f55 */\n.hero{flex:0 0 auto;display:grid;grid-template-columns:minmax(0,1fr) auto;grid-template-areas:\"top undo\" \"time undo\";align-items:center;column-gap:6px;min-height:58px;padding:6px 6px 6px 10px;border-radius:14px;background:var(--accent);color:var(--on-accent)}\n.hero.flash{animation:pop .6s ease-out}\n@keyframes pop{0%{transform:scale(.95)}55%{transform:scale(1.02)}100%{transform:scale(1)}}\n.hero-top{grid-area:top;display:flex;align-items:baseline;gap:4px;min-width:0;line-height:1.3}\n.hero-ic{display:none}\n.hero-type{flex:0 0 auto;font-size:13px;font-weight:800;white-space:nowrap}\n.hero-ago{flex:1 1 auto;min-width:0;font-size:11px;opacity:.92;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.hero-time{grid-area:time;display:flex;align-items:baseline;gap:5px;min-width:0;overflow:hidden;line-height:1.1;font-variant-numeric:tabular-nums}\n.hero-clock{flex:0 0 auto;font-size:26px;font-weight:800;letter-spacing:.5px}\n.hero-day{flex:0 1 auto;min-width:0;font-size:12px;font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.hero-none{font-size:19px;font-weight:800;white-space:nowrap}\n.undo{grid-area:undo;align-self:center;min-width:44px;height:40px;padding:0 6px;border-radius:12px;border:1.5px solid currentColor;display:inline-flex;align-items:center;justify-content:center;font-size:14px;font-weight:800;white-space:nowrap}\n.undo:active{opacity:.6}\n.undo:disabled{opacity:.4}\n.undo:focus-visible{outline-color:var(--on-accent)}\n\n/* \u56db\u4e2a\u5927\u6309\u94ae */\n.pad{flex:1 1 0;min-height:0;min-width:0;display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);grid-template-rows:minmax(0,1fr) minmax(0,1fr);gap:6px}\n.act{min-width:0;min-height:0;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px;padding:4px;border-radius:14px;background:var(--soft);border:1.5px solid var(--line);color:var(--ink);transition:transform .08s}\n.act .ic{flex:0 0 auto;width:20px;height:20px;color:var(--accent)}\n.act-sleep .ic,.act-diaper .ic{color:var(--accent-alt)}\n.act .tx{min-width:0;display:flex;flex-direction:column;align-items:center}\n.act .nm{font-size:16px;font-weight:800;line-height:1.2;white-space:nowrap}\n.act .sub{display:none;font-size:11px;line-height:1.3;color:var(--muted);white-space:nowrap}\n.act:active{transform:scale(.96);background:var(--accent);border-color:var(--accent);color:var(--on-accent)}\n.act:active .ic,.act:active .sub{color:var(--on-accent)}\n\n/* \u63d0\u793a */\n.err{position:absolute;left:8px;right:8px;bottom:8px;z-index:2;padding:8px 10px;border-radius:10px;background:var(--ink);color:var(--paper);font-size:13px;font-weight:700}\n\n/* \u5386\u53f2\u5217\u8868\uff083x6 / 6x6\uff09 */\n.hist{flex:1 1 0;min-height:0;min-width:0;overflow-x:hidden;overflow-y:auto;padding:0 8px;border-radius:12px;border:1px solid var(--line);background:var(--panel-paper);-webkit-overflow-scrolling:touch}\n.day{padding:8px 0 2px;font-size:12px;font-weight:700;color:var(--muted)}\n.row{display:flex;align-items:center;gap:8px;min-height:40px;border-bottom:1px solid var(--line)}\n.row-ic{flex:0 0 auto;width:18px;height:18px;color:var(--accent)}\n.row-nm{min-width:0;font-size:15px;font-weight:700;white-space:nowrap}\n.row-time{margin-left:auto;font-size:15px;font-variant-numeric:tabular-nums;white-space:nowrap}\n.del{flex:0 0 auto;width:40px;height:40px;margin-right:-8px;border-radius:10px;font-size:22px;line-height:1;color:var(--muted);display:inline-flex;align-items:center;justify-content:center}\n.del:active{background:var(--soft);color:var(--ink)}\n.hist-empty{padding:16px 4px;text-align:center;font-size:13px;color:var(--muted)}\n\n/* 194 x 404\uff1a\u7ad6\u957f\uff0c\u6309\u94ae\u653e\u5927\uff0c\u4e0b\u9762\u63a5\u5386\u53f2 */\n.card[data-size=\"3x6\"] .hero{min-height:72px;padding:8px 6px 8px 10px}\n.card[data-size=\"3x6\"] .hero-type{font-size:15px}\n.card[data-size=\"3x6\"] .hero-ago{font-size:12px}\n.card[data-size=\"3x6\"] .hero-clock{font-size:28px}\n.card[data-size=\"3x6\"] .pad{flex:0 0 156px}\n.card[data-size=\"3x6\"] .act .ic{width:28px;height:28px}\n.card[data-size=\"3x6\"] .act .nm{font-size:17px}\n\n/* 404 x 194\uff1a\u5de6\u8fb9\u6700\u8fd1\u4e00\u6b21\uff0c\u53f3\u8fb9\u56db\u4e2a\u5927\u6309\u94ae */\n.card[data-size=\"6x3\"]{flex-direction:row}\n.card[data-size=\"6x3\"] .hero{flex:0 0 44%;min-width:0;align-self:stretch;grid-template-columns:auto minmax(0,1fr) auto;grid-template-rows:auto 1fr auto;grid-template-areas:\"icon type type\" \"time time time\" \"ago ago undo\";align-items:center;column-gap:6px;row-gap:2px;padding:10px 10px 10px 12px}\n.card[data-size=\"6x3\"] .hero-top{display:contents}\n.card[data-size=\"6x3\"] .hero-ic{display:block;grid-area:icon;width:18px;height:18px}\n.card[data-size=\"6x3\"] .hero-type{grid-area:type;font-size:15px}\n.card[data-size=\"6x3\"] .hero-ago{grid-area:ago;font-size:12px}\n.card[data-size=\"6x3\"] .hero-clock{font-size:38px}\n.card[data-size=\"6x3\"] .hero-day{font-size:13px}\n.card[data-size=\"6x3\"] .hero-none{font-size:22px}\n.card[data-size=\"6x3\"] .undo{min-width:56px;height:42px;font-size:15px}\n.card[data-size=\"6x3\"] .pad{flex:1 1 0}\n.card[data-size=\"6x3\"] .act .ic{width:24px;height:24px}\n.card[data-size=\"6x3\"] .act .nm{font-size:18px}\n.card[data-size=\"6x3\"] .act .sub{display:block}\n\n/* 404 x 404\uff1a\u5927\u5361\uff0c\u6700\u8fd1\u4e00\u6b21\u52a0\u5927\uff0c\u6309\u94ae\u6a2a\u6392\u56fe\u6807\uff0c\u4e0b\u9762\u662f\u5386\u53f2 */\n.card[data-size=\"6x6\"]{gap:8px;padding:10px}\n.card[data-size=\"6x6\"] .hero{min-height:98px;padding:10px 10px 10px 16px;column-gap:10px}\n.card[data-size=\"6x6\"] .hero-top{gap:8px}\n.card[data-size=\"6x6\"] .hero-ic{display:block;flex:0 0 auto;align-self:center;width:20px;height:20px}\n.card[data-size=\"6x6\"] .hero-type{font-size:17px}\n.card[data-size=\"6x6\"] .hero-ago{font-size:14px}\n.card[data-size=\"6x6\"] .hero-clock{font-size:44px}\n.card[data-size=\"6x6\"] .hero-day{font-size:15px}\n.card[data-size=\"6x6\"] .hero-none{font-size:26px}\n.card[data-size=\"6x6\"] .undo{min-width:68px;height:48px;font-size:16px;border-radius:14px}\n.card[data-size=\"6x6\"] .pad{flex:0 0 148px;gap:8px}\n.card[data-size=\"6x6\"] .act{flex-direction:row;gap:12px;padding:6px 12px}\n.card[data-size=\"6x6\"] .act .ic{width:34px;height:34px}\n.card[data-size=\"6x6\"] .act .tx{align-items:flex-start}\n.card[data-size=\"6x6\"] .act .nm{font-size:21px}\n.card[data-size=\"6x6\"] .act .sub{display:block;font-size:12px}\n";
const TYPES=[
  {k:'feed',name:'喝奶'},
  {k:'sleep',name:'入睡'},
  {k:'wake',name:'睡醒'},
  {k:'diaper',name:'换尿布'}
];
const ICONS={
  feed:['M12 2.5c-1 0-1.8.8-1.8 1.8V6h3.6V4.3c0-1-.8-1.8-1.8-1.8z','M8.5 6h7v2.5h-7z','M8 8.5h8v11a2 2 0 0 1-2 2h-4a2 2 0 0 1-2-2z','M8 12.5h3M8 15.5h3M8 18.5h3'],
  sleep:['M20 14.2A8 8 0 1 1 9.8 4 6.5 6.5 0 0 0 20 14.2z','M17.5 3.5v3M16 5h3'],
  wake:['M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0z','M12 2.5v2.5M12 19v2.5M2.5 12H5M19 12h2.5M5.3 5.3l1.8 1.8M16.9 16.9l1.8 1.8M5.3 18.7l1.8-1.8M16.9 7.1l1.8-1.8'],
  diaper:['M3.5 6.5h17v4.2c0 3.2-2.6 5.2-5 6.2l-.8 1.9H9.3l-.8-1.9c-2.4-1-5-3-5-6.2z','M3.5 10h4M16.5 10h4']
};

function typeName(k){
  for(let i=0;i<TYPES.length;i++){if(TYPES[i].k===k)return TYPES[i].name;}
  return '';
}

function icon(k,cls){
  const NS='http://www.w3.org/2000/svg';
  const svg=document.createElementNS(NS,'svg');
  svg.setAttribute('viewBox','0 0 24 24');
  svg.setAttribute('fill','none');
  svg.setAttribute('stroke','currentColor');
  svg.setAttribute('stroke-width','1.9');
  svg.setAttribute('stroke-linecap','round');
  svg.setAttribute('stroke-linejoin','round');
  svg.setAttribute('aria-hidden','true');
  svg.setAttribute('class',cls||'');
  (ICONS[k]||[]).forEach(d=>{
    const p=document.createElementNS(NS,'path');
    p.setAttribute('d',d);
    svg.appendChild(p);
  });
  return svg;
}

function pad2(n){return n<10?'0'+n:''+n;}
function fmtTime(ts){const d=new Date(ts);return pad2(d.getHours())+':'+pad2(d.getMinutes());}
function dayKey(ts){const d=new Date(ts);return d.getFullYear()+'-'+pad2(d.getMonth()+1)+'-'+pad2(d.getDate());}
function dayLabel(ts){
  const now=Date.now();
  const k=dayKey(ts);
  if(k===dayKey(now))return '今天';
  if(k===dayKey(now-86400000))return '昨天';
  const d=new Date(ts);
  return (d.getMonth()+1)+'月'+d.getDate()+'日';
}
function shortDay(ts){
  const now=Date.now();
  const k=dayKey(ts);
  if(k===dayKey(now-86400000))return '昨天';
  const d=new Date(ts);
  return (d.getMonth()+1)+'/'+d.getDate();
}
function ago(ts){
  const m=Math.floor((Date.now()-ts)/60000);
  if(m<1)return '刚刚';
  if(m<60)return m+'分钟前';
  const h=Math.floor(m/60);
  const r=m%60;
  if(h<24)return r?h+'小时'+r+'分前':h+'小时前';
  return Math.floor(h/24)+'天前';
}

function readLogs(s){
  const raw=s&&Array.isArray(s.logs)?s.logs:[];
  const out=[];
  raw.forEach(x=>{
    if(x&&typeof x.id==='string'&&typeof x.ts==='number'&&typeName(x.type))out.push(x);
  });
  out.sort((a,b)=>a.ts-b.ts);
  return out;
}

function mount(ctx){
  const {root,el,state,ui,update,redraw,uid,size}=ctx;
  const logs=readLogs(state);
  const latest=logs.length?logs[logs.length-1]:null;
  const ticks=[];
  const timers=[];

  function fail(){
    ui.err='保存失败，请再点一次';
    ui.flashId=null;
    redraw();
  }
  function record(type){
    const ts=Date.now();
    const id=uid();
    ui.err=null;
    ui.flashId=id;
    ui.histTop=0;
    update(s=>{
      const cur=readLogs(s);
      const prev=cur.length?cur[cur.length-1]:null;
      // 同一类型 1.5 秒内的连点视为误触，忽略
      if(prev&&prev.type===type&&ts-prev.ts>=0&&ts-prev.ts<1500)return s;
      const base=Array.isArray(s&&s.logs)?s.logs:[];
      return Object.assign({},s,{logs:base.concat([{id:id,type:type,ts:ts}])});
    }).catch(fail);
  }
  function remove(id){
    ui.err=null;
    ui.flashId=null;
    update(s=>{
      const base=Array.isArray(s&&s.logs)?s.logs:[];
      return Object.assign({},s,{logs:base.filter(x=>!(x&&x.id===id))});
    }).catch(fail);
  }
  function agoNode(ts,cls){
    const n=el('span',{class:cls},ago(ts));
    ticks.push(()=>{n.textContent=ago(ts);});
    return n;
  }
  function lastOf(k){
    for(let i=logs.length-1;i>=0;i--){if(logs[i].type===k)return logs[i];}
    return null;
  }

  // 最近一次记录（醒目区）
  const topKids=[];
  const timeKids=[];
  if(latest){
    topKids.push(icon(latest.type,'hero-ic'));
    topKids.push(el('span',{class:'hero-type'},typeName(latest.type)));
    topKids.push(agoNode(latest.ts,'hero-ago'));
    if(dayKey(latest.ts)!==dayKey(Date.now())){
      timeKids.push(el('span',{class:'hero-day'},shortDay(latest.ts)));
    }
    timeKids.push(el('span',{class:'hero-clock'},fmtTime(latest.ts)));
  }else{
    topKids.push(el('span',{class:'hero-type'},'最近一次'));
    if(size!=='3x3')topKids.push(el('span',{class:'hero-ago'},'点按钮记一笔'));
    timeKids.push(el('span',{class:'hero-none'},'还没有记录'));
  }
  const undo=el('button',{
    type:'button',
    class:'undo',
    disabled:!latest,
    'aria-label':latest?'撤回最近一次'+typeName(latest.type)+'记录':'没有可撤回的记录',
    onclick:()=>{if(latest)remove(latest.id);}
  },el('span',{class:'undo-tx'},'撤回'));
  const flash=!!(latest&&ui.flashId===latest.id);
  const hero=el('div',{class:'hero'+(flash?' flash':'')},
    el('div',{class:'hero-top'},...topKids),
    el('div',{class:'hero-time'},...timeKids),
    undo);
  if(flash){
    timers.push(setTimeout(()=>{ui.flashId=null;hero.classList.remove('flash');},1000));
  }

  // 四个大按钮
  const pad=el('div',{class:'pad'},...TYPES.map(t=>{
    const last=lastOf(t.k);
    const sub=el('span',{class:'sub'},last?ago(last.ts):'未记录');
    if(last)ticks.push(()=>{sub.textContent=ago(last.ts);});
    return el('button',{
      type:'button',
      class:'act act-'+t.k,
      'aria-label':'记录'+t.name,
      onclick:()=>record(t.k)
    },icon(t.k,'ic'),el('span',{class:'tx'},el('span',{class:'nm'},t.name),sub));
  }));

  // 历史（高尺寸才显示，可滚动，全部记录可达）
  let hist=null;
  if(size==='3x6'||size==='6x6'){
    const kids=[];
    if(!logs.length){
      kids.push(el('div',{class:'hist-empty'},'记录会按时间排在这里'));
    }else{
      const rev=logs.slice().reverse();
      const counts={};
      rev.forEach(x=>{const k=dayKey(x.ts);counts[k]=(counts[k]||0)+1;});
      let cur='';
      rev.forEach(x=>{
        const k=dayKey(x.ts);
        if(k!==cur){
          cur=k;
          kids.push(el('div',{class:'day'},dayLabel(x.ts)+' · '+counts[k]+'条'));
        }
        kids.push(el('div',{class:'row'},
          icon(x.type,'row-ic'),
          el('span',{class:'row-nm'},typeName(x.type)),
          el('span',{class:'row-time'},fmtTime(x.ts)),
          el('button',{
            type:'button',
            class:'del',
            'aria-label':'删除 '+typeName(x.type)+' '+fmtTime(x.ts),
            onclick:()=>remove(x.id)
          },'×')));
      });
    }
    hist=el('div',{class:'hist',onscroll:()=>{ui.histTop=hist.scrollTop;}},...kids);
  }

  root.appendChild(hero);
  root.appendChild(pad);
  if(hist){
    root.appendChild(hist);
    hist.scrollTop=ui.histTop||0;
  }
  if(ui.err){
    const errNode=el('div',{class:'err'},'! '+ui.err);
    root.appendChild(errNode);
    timers.push(setTimeout(()=>{ui.err=null;errNode.remove();},4000));
  }

  const iv=setInterval(()=>{ticks.forEach(f=>f());},20000);
  return ()=>{
    clearInterval(iv);
    timers.forEach(t=>clearTimeout(t));
  };
}

